int logfmt_parse_multi(const char *in, char **keys, char **vals, size_t *num_pairs) {
    size_t num_pairs_found = 0;
    const char *start = in;

    while (in) {
        const char *end = strchr(in, ' ');
        if (!end) end = in + strlen(in);

        if (*in == ' ') {
            in++;
            continue;
        }

        const char *eq = strchr(in, '=');
        if (!eq) break;

        size_t klen = (size_t)(eq - in);
        if (klen > 0) {
            keys[num_pairs_found] = malloc(klen + 1);
            strncpy(keys[num_pairs_found], in, klen);
            keys[num_pairs_found][klen] = '\0';

            const char *val_start = eq + 1;
            if (*val_start == '"') {
                const char *quote_end = strchr(val_start + 1, '"');
                if (!quote_end) break;
                size_t vlen = (size_t)(quote_end - val_start - 1);
                vals[num_pairs_found] = malloc(vlen + 1);
                strncpy(vals[num_pairs_found], val_start + 1, vlen);
                vals[num_pairs_found][vlen] = '\0';
            } else {
                size_t vlen = 0;
                while (val_start[vlen] != '\0' && val_start[vlen] != ' ') {
                    vlen++;
                }
                vals[num_pairs_found] = malloc(vlen + 1);
                strncpy(vals[num_pairs_found], val_start, vlen);
                vals[num_pairs_found][vlen] = '\0';
            }

            num_pairs_found++;
        }

        in = end;
    }

    *num_pairs = num_pairs_found;
    return 0;
}

